-- Read-only preflight. Run in your project's SQL editor before approving migrations.
-- Returns schema metadata only; no employee rows, keys, passwords or object contents.
begin read only;
set local statement_timeout='15s';
select current_setting('server_version') postgres_version,current_setting('server_version_num')::int>=150000 supports_security_invoker_views;
select name,installed_version,default_version from pg_available_extensions where name in ('pgcrypto','btree_gist');
select name,to_regclass(name) is not null present from unnest(array['auth.users','storage.buckets','storage.objects']) name;
select to_regprocedure('auth.uid()') is not null auth_uid_present;
select rolname from pg_roles where rolname in ('anon','authenticated','service_role');
select n.nspname schema_name,c.relname,c.relkind,c.relrowsecurity,c.reloptions from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','v','p','m') order by c.relname;
select p.proname,pg_get_function_identity_arguments(p.oid) arguments,p.prosecdef security_definer,p.proconfig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['has_role','can_access','audit_change','can_access_document','payroll_round','apply_payroll_policy','create_company','set_membership','enforce_employee_scope','validate_leave','request_leave','review_correction','schedule_recovery','generate_payroll','transition_payroll','record_payment','reverse_payment','protect_financial_source','ingest_device_events','save_attendance','review_absence','review_request','employee_directory','validate_mapping','guard_payroll_sources','default_pending','freeze_period','validate_recovery_source','record_salary_history','guard_correction','freeze_payroll_attendance','backfill_device_mappings','employee_counts','dashboard_metrics','run_maintenance','service_save_attendance','attendance_employee','analytics_series','transfer_device_mappings','guard_payroll_request','recovery_incidents','request_correction','request_advance','guard_employee_payroll_overlap','validate_scheduled_leave_days']) order by p.proname;
select schemaname,tablename,policyname,roles,cmd from pg_policies where schemaname='public' and tablename=any(array['companies','company_memberships','branches','departments','positions','employees','employee_contacts','employee_guarantors','employee_documents','employment_contracts','salary_structures','salary_history','attendance_devices','device_employee_mappings','raw_attendance_events','attendance_summaries','attendance_corrections','attendance_sync_logs','work_shifts','shift_assignments','leave_types','leave_policies','leave_requests','overtime_records','employee_incidents','damage_recovery_plans','damage_recovery_installments','salary_advances','advance_repayments','payroll_periods','payroll_runs','payroll_items','payroll_approvals','salary_payments','payment_allocations','employee_performance_reviews','notifications','application_settings','holidays','authorized_deductions','audit_logs']) order by tablename,policyname;
select table_name,grantee,privilege_type from information_schema.role_table_grants where table_schema='public' and table_name=any(array['companies','company_memberships','branches','departments','positions','employees','employee_contacts','employee_guarantors','employee_documents','employment_contracts','salary_structures','salary_history','attendance_devices','device_employee_mappings','raw_attendance_events','attendance_summaries','attendance_corrections','attendance_sync_logs','work_shifts','shift_assignments','leave_types','leave_policies','leave_requests','overtime_records','employee_incidents','damage_recovery_plans','damage_recovery_installments','salary_advances','advance_repayments','payroll_periods','payroll_runs','payroll_items','payroll_approvals','salary_payments','payment_allocations','employee_performance_reviews','notifications','application_settings','holidays','authorized_deductions','audit_logs']) and grantee in ('anon','authenticated','service_role') order by table_name,grantee,privilege_type;
select id,public,file_size_limit,allowed_mime_types from storage.buckets where id='employee-documents';
select to_regclass('supabase_migrations.schema_migrations') is not null migration_history_present;
rollback;
